// src/test/scala/CalcSuite.scala
class CalcSuite extends munit.FunSuite:
  def divide(a: Int, b: Int): Either[String, Int] =
    if b == 0 then Left("division by zero") else Right(a / b)

  test("divides evenly") {
    assertEquals(divide(10, 2), Right(5))
  }
  test("rejects zero") {
    assert(divide(1, 0).isLeft)
  }
// $ sbt test   -> + divides evenly, + rejects zero, Passed: Total 2

import scala.compiletime.{error, constValue, erasedValue}

inline def power(x: Double, inline n: Int): Double =
  inline if n == 0 then 1.0
  else inline if n % 2 == 1 then x * power(x, n - 1)
  else power(x * x, n / 2)                    // unrolled at compile time

inline def checkedPort(inline p: Int): Int =
  inline if p < 1 || p > 65535 then error("port out of range") else p

inline def typeName[T]: String = inline erasedValue[T] match
  case _: Int    => "Int"
  case _: String => "String"
  case _         => "other"
type Size = 3
@main def meta(): Unit =
  println(power(2.0, 10))                     // 1024.0
  println(checkedPort(8080))                  // 8080
  // checkedPort(70000)                       // compile error: port out of range
  println(typeName[String])                   // String
  println(constValue[Size] * 2)               // 6
